-- MinVandrings recept från supabase/katalog/recept/ (recept.csv, ingredienser.csv och steg.csv).
-- Skapad med "npm run receptkatalog". Ändra inte filen för hand: ändra CSV:erna och skapa en ny migrering.

delete from public.receptkatalog where id not in ('aprikosgrot', 'appelgranola', 'fullkornsrisgrot', 'havreplattar', 'kall-barmusli', 'jordnotstortilla', 'pastasallad', 'bonsallad', 'paprikahummus', 'tonfiskwrap', 'bonwrap', 'tortellini', 'currycouscous', 'rotmos-korv', 'bulgurgryta', 'falafel', 'couscous-jordnot', 'tacoris', 'jordnotsnudlar', 'havregryta', 'svamprisotto', 'appelringar', 'notmix', 'havrerutor', 'nutellarulle', 'kvallskakao', 'matchalatte', 'blodapelsin', 'blabarssoppa');

on conflict (id) do update set
  namn = excluded.namn,
  maltid = excluded.maltid,
  portioner = excluded.portioner,
  kok_kravs = excluded.kok_kravs,
  torkning_hemma = excluded.torkning_hemma,
  beskrivning = excluded.beskrivning,
  mangder = excluded.mangder,
  inspirerat_av = excluded.inspirerat_av,
  inspirerat_av_url = excluded.inspirerat_av_url,
  status = excluded.status,
  bild = excluded.bild;

delete from public.receptkatalog_ingredienser where recept_id in ('aprikosgrot', 'appelgranola', 'fullkornsrisgrot', 'havreplattar', 'kall-barmusli', 'jordnotstortilla', 'pastasallad', 'bonsallad', 'paprikahummus', 'tonfiskwrap', 'bonwrap', 'tortellini', 'currycouscous', 'rotmos-korv', 'bulgurgryta', 'falafel', 'couscous-jordnot', 'tacoris', 'jordnotsnudlar', 'havregryta', 'svamprisotto', 'appelringar', 'notmix', 'havrerutor', 'nutellarulle', 'kvallskakao', 'matchalatte', 'blodapelsin', 'blabarssoppa');
delete from public.receptkatalog_steg where recept_id in ('aprikosgrot', 'appelgranola', 'fullkornsrisgrot', 'havreplattar', 'kall-barmusli', 'jordnotstortilla', 'pastasallad', 'bonsallad', 'paprikahummus', 'tonfiskwrap', 'bonwrap', 'tortellini', 'currycouscous', 'rotmos-korv', 'bulgurgryta', 'falafel', 'couscous-jordnot', 'tacoris', 'jordnotsnudlar', 'havregryta', 'svamprisotto', 'appelringar', 'notmix', 'havrerutor', 'nutellarulle', 'kvallskakao', 'matchalatte', 'blodapelsin', 'blabarssoppa');



-- En märkesvara som inte finns i varukatalogen ger en tom koppling. Då stoppas migreringen i stället.
do $$ begin
  if (select count(*) from public.receptkatalog_ingredienser where varukatalog_id is not null) <> 77 then
    raise exception 'En märkesvara i receptkatalogen finns inte i varukatalogen';
  end if;
end $$;
