insert into public.receptkatalog_steg (recept_id, steg_nr, var, steg, tid_min) values
  ('aprikosgrot', 1, 'hemma', 'Blanda gryn, mjölkpulver, aprikoser, socker och kanel i en påse.', null),
  ('aprikosgrot', 2, 'hemma', 'Packa ghee och valnötter för sig.', null),
  ('aprikosgrot', 3, 'turen', 'Koka upp vattnet, häll i grötblandningen och rör om.', null),
  ('aprikosgrot', 4, 'turen', 'Låt gröten svälla under lock.', '1'),
  ('aprikosgrot', 5, 'turen', 'Rör ner ghee och strö över valnötterna.', null),
  ('appelgranola', 1, 'hemma', 'Sätt ugnen på 160 °C. Blanda havregryn, kanel, honung och olja.', null),
  ('appelgranola', 2, 'hemma', 'Rosta på en plåt tills grynen är gyllene. Rör om några gånger.', '30–40'),
  ('appelgranola', 3, 'hemma', 'Låt svalna och blanda i äpple och chiafrön.', null),
  ('appelgranola', 4, 'hemma', 'Dela upp i fyra påsar och lägg 2 msk mjölkpulver i varje.', null),
  ('appelgranola', 5, 'turen', 'Koka upp 1,2 dl vatten per portion, häll över granolan och rör om.', null),
  ('fullkornsrisgrot', 1, 'hemma', 'Koka fullkornsriset, torka det och grovmal det.', null),
  ('fullkornsrisgrot', 2, 'hemma', 'Blanda riset med mjölkpulver, socker, kanel, äpple och linfrö i en påse. Packa ghee för sig.', null),
  ('fullkornsrisgrot', 3, 'turen', 'Koka upp vattnet och häll det över blandningen.', null),
  ('fullkornsrisgrot', 4, 'turen', 'Rör om och låt stå varmt under lock.', '5'),
  ('fullkornsrisgrot', 5, 'turen', 'Rör ner ghee innan du äter.', null),
  ('havreplattar', 1, 'hemma', 'Blanda mjöl, mjölkpulver, bakpulver och socker i en påse. Packa ghee för sig.', null),
  ('havreplattar', 2, 'turen', 'Rör ut torrmixen med vattnet till en jämn smet.', null),
  ('havreplattar', 3, 'turen', 'Låt smeten vila.', '5'),
  ('havreplattar', 4, 'turen', 'Smält lite ghee i pannan och stek små plättar på båda sidor tills de fått färg.', null),
  ('kall-barmusli', 1, 'hemma', 'Blanda müsli, mjölkpulver och bär i en påse.', null),
  ('kall-barmusli', 2, 'turen', 'Häll i kallt vatten och rör tills mjölkpulvret har löst sig.', null),
  ('jordnotstortilla', 1, 'hemma', 'Packa bröd, jordnötssmör och sylt för sig.', null),
  ('jordnotstortilla', 2, 'turen', 'Bred jordnötssmör och sylt på bröden och rulla ihop.', null),
  ('pastasallad', 1, 'hemma', 'Koka makaronerna en minut kortare än det står på paketet och skölj dem kalla. Låt kikärterna rinna av.', null),
  ('pastasallad', 2, 'hemma', 'Tärna grönsakerna och lägg ut allt glest på torkbrickor.', null),
  ('pastasallad', 3, 'hemma', 'Torka i cirka 52 °C tills även de tjockaste bitarna är helt torra.', '360–600'),
  ('pastasallad', 4, 'hemma', 'Packa det torkade med kryddorna. Packa olja och citronpulver för sig.', null),
  ('pastasallad', 5, 'turen', 'Häll kallt vatten över i en tät burk.', null),
  ('pastasallad', 6, 'turen', 'Låt dra tills pastan är mjuk.', '90'),
  ('pastasallad', 7, 'turen', 'Rör ner olja och citronpulver.', null),
  ('bonsallad', 1, 'hemma', 'Hacka och tärna grönsakerna. Lägg bönor, majs och grönsaker glest på torkbrickor, tomaterna för sig.', null),
  ('bonsallad', 2, 'hemma', 'Torka i cirka 52 °C tills allt är genomtorrt.', null),
  ('bonsallad', 3, 'hemma', 'Låt svalna och packa med kryddorna. Packa lime och olja för sig.', null),
  ('bonsallad', 4, 'turen', 'Häll kallt vatten över i en tät burk.', null),
  ('bonsallad', 5, 'turen', 'Låt dra och skaka burken då och då.', '60'),
  ('bonsallad', 6, 'turen', 'Rör ner olja och lime när bönorna är mjuka.', null),
  ('paprikahummus', 1, 'hemma', 'Mal sesamfröna och låt kikärterna rinna av.', null),
